mapper.select:

SELECT id, run_kind AS runKind, run_id AS runId, seq, request_id AS requestId,
       parent_request_id AS parentRequestId, workspace_id AS workspaceId, subject,
       trace_id AS traceId, agent_version_id AS agentVersionId, spec_hash AS specHash,
       grant_id AS grantId, manifest_json::text AS manifestJson, content_hash AS contentHash,
       prev_hash AS prevHash, hash, create_at AS createAt, create_by AS createBy
  FROM run_manifest
 WHERE run_kind = #{runKind}


 AND workspace_id = #{workspaceId} 


 AND agent_version_id = #{agentVersionId} 


 ORDER BY create_at DESC, id DESC
 LIMIT #{limit}


SELECT id, run_kind AS runKind, run_id AS runId, seq, request_id AS requestId,
       parent_request_id AS parentRequestId, workspace_id AS workspaceId, subject,
       trace_id AS traceId, agent_version_id AS agentVersionId, spec_hash AS specHash,
       grant_id AS grantId, manifest_json::text AS manifestJson, content_hash AS contentHash,
       prev_hash AS prevHash, hash, create_at AS createAt, create_by AS createBy
  FROM run_manifest
 WHERE 1 = 1


 AND workspace_id = #{workspaceId} 


 AND request_id = #{requestId} 


 AND subject = #{subject} 


 ORDER BY create_at ASC, id ASC
 LIMIT #{limit}
